record.field:
sign_template_model = env['sign.template'].sudo()
sign_document_model = env['sign.document'].sudo()
sign_item_model = env['sign.item'].sudo()
sign_role_model = env['sign.item.role'].sudo()
sign_send_model = env['sign.send.request'].sudo()
sign_send_signer_model = env['sign.send.request.signer'].sudo()
sign_request_model = env['sign.request'].sudo()
partner_model = env['res.partner'].sudo()

signature_type = env.ref('sign.sign_item_type_signature', raise_if_not_found=False)

action = False


def toast(title, message, kind='warning', sticky=False, next_action=False):
    params = {
        'title': title,
        'message': message,
        'type': kind,
        'sticky': sticky,
    }
    if next_action:
        params['next'] = next_action
    return {'type': 'ir.actions.client', 'tag': 'display_notification', 'params': params}


def reload_item(rec):
    view = env.ref('hr_employment_custom.view_employee_custody_item_form', raise_if_not_found=False)
    action = {
        'type': 'ir.actions.act_window',
        'name': rec.x_name or 'Employee Custody Item',
        'res_model': rec._name,
        'res_id': rec.id,
        'view_mode': 'form',
        'target': 'current',
    }
    if view:
        action['views'] = [(view.id, 'form')]
    return action


def get_or_create_role(name, fallbacks):
    role = sign_role_model.search([('name', '=', name)], order='id asc', limit=1)
    if role:
        return role
    for fallback in fallbacks:
        role = sign_role_model.search([('name', '=', fallback)], order='id asc', limit=1)
        if role:
            return role
    return sign_role_model.create({'name': name})


def employee_partner(employee):
    if not employee:
        return False
    partner = False
    if 'work_contact_id' in employee._fields and employee.work_contact_id:
        partner = employee.work_contact_id.sudo()
    if not partner and 'user_id' in employee._fields and employee.user_id and employee.user_id.partner_id:
        partner = employee.user_id.partner_id.sudo()
    email = employee.work_email if 'work_email' in employee._fields else False
    if not partner and email:
        partner = partner_model.search([('email', '=', email)], order='id asc', limit=1)
    if not partner and email:
        partner = partner_model.create({
            'name': employee.name or email,
            'email': email,
        })
    return partner


if not signature_type:
    action = toast('Odoo Sign setup missing', 'Signature field type sign.sign_item_type_signature was not found.', 'warning', True)
else:
    employee_role = get_or_create_role('Employee', ['Applicant', 'Customer', 'Signatory'])

    for rec in records.sudo():
        employee = rec.x_employee_id.sudo() if rec.x_employee_id else False
        custody_type = rec.x_custody_type_id.sudo() if rec.x_custody_type_id else False

        if not employee:
            action = toast('Missing employee', 'This custody item has no linked employee.', 'warning', True, reload_item(rec))
            continue

        if not custody_type:
            action = toast('Missing custody type', 'Select a custody type before sending F-0011 to Sign.', 'warning', True, reload_item(rec))
            continue

        if not custody_type.x_uses_company_id_document and custody_type.x_category != 'company_id_card':
            action = toast('Unsupported custody type', 'F-0011 Sign is enabled only for the Company ID Card custody type in Pass 16.', 'warning', False, reload_item(rec))
            continue

        if rec.x_state == 'signed' or rec.x_signed_attachment_id:
            action = toast('Already signed', 'This custody receipt is already signed.', 'warning', False, reload_item(rec))
            continue

        if rec.x_state != 'generated' or not rec.x_pdf_attachment_id:
            action = toast('Generate PDF first', 'Generate the F-0011 PDF before sending it to Odoo Sign.', 'warning', False, reload_item(rec))
            continue

        if rec.x_sign_request_res_id:
            existing_request = sign_request_model.browse(rec.x_sign_request_res_id)
            if existing_request.exists() and (existing_request.state or '') not in ('cancelled', 'canceled'):
                action = toast('Duplicate Sign request blocked', 'An active Odoo Sign request already exists for this custody receipt. Use Sync instead.', 'warning', True, reload_item(rec))
                continue

        employee_sign_partner = employee_partner(employee)

        if not employee_sign_partner or not employee_sign_partner.email:
            action = toast('Missing employee email', 'The employee needs a partner/work contact with email before sending F-0011 to Sign.', 'warning', True, reload_item(rec))
            continue

        pdf_attachment = rec.x_pdf_attachment_id.sudo()
        filename = pdf_attachment.name or ('%s - Company ID Card Receipt.pdf' % (rec.x_document_reference or 'MCEP-HR-F0011'))
        sent_on = datetime.datetime.now()
        validity_date = datetime.date.today() + datetime.timedelta(days=60)

        sign_template = sign_template_model.create({
            'name': filename,
            'user_id': env.user.id,
            'signature_request_validity': 60,
        })

        sign_document = sign_document_model.create({
            'template_id': sign_template.id,
            'attachment_id': pdf_attachment.id,
            'name': filename,
            'sequence': 1,
        })

        # F-0011 geometry:
        # one employee signature item only.
        # Date is already generated into the PDF, so no date Sign item is created.
        sign_item_model.create({
            'document_id': sign_document.id,
            'type_id': signature_type.id,
            'responsible_id': employee_role.id,
            'page': 1,
            'posX': 0.250,
            'posY': 0.805,
            'width': 0.290,
            'height': 0.040,
            'required': True,
            'name': 'Employee Signature',
            'alignment': 'left',
            'constant': False,
        })

        subject = 'Signature Request - %s' % filename
        body = '<p>Please review and sign the attached F-0011 Company ID Card Receipt.</p>'

        send_request = sign_send_model.create({
            'template_id': sign_template.id,
            'signer_id': employee_sign_partner.id,
            'subject': subject,
            'body': body,
            'validity': validity_date,
            'certificate_reference': False,
            'reminder_enabled': False,
            'model': 'x_hr.employee_custody_item',
            'res_ids': str([rec.id]),
        })

        signer_line = send_request.signer_ids.filtered(lambda line: line.role_id.id == employee_role.id)[:1]
        if signer_line:
            signer_line.sudo().write({
                'partner_id': employee_sign_partner.id,
                'mail_sent_order': 1,
            })
        else:
            sign_send_signer_model.create({
                'sign_send_request_id': send_request.id,
                'role_id': employee_role.id,
                'partner_id': employee_sign_partner.id,
                'mail_sent_order': 1,
            })

        send_request.send_request()

        generated_request = sign_request_model.search([
            ('template_id', '=', sign_template.id),
        ], order='create_date desc, id desc', limit=1)

        if generated_request:
            rec.write({
                'x_state': 'signature_requested',
                'x_sent_on': sent_on,
                'x_sign_request_res_id': generated_request.id,
                'x_sign_request_state': generated_request.state or 'sent',
                'x_sign_request_reference': generated_request.reference or filename,
                'x_sign_request_url': '/odoo/sign/%s' % generated_request.id,
                'x_responsible_user_id': env.user.id,
                'x_notes': ((rec.x_notes or '') + '\nNative Odoo Sign request created for F-0011 on %s. Request ID: %s. Employee: %s.' % (sent_on, generated_request.id, employee_sign_partner.display_name)).strip(),
            })

            employee.message_post(
                body='تم إرسال نموذج استلام البطاقة التعريفية F-0011 للتوقيع عبر توقيع أودو. رقم طلب التوقيع: %s.' % generated_request.id,
                subtype_xmlid='mail.mt_note',
                attachment_ids=[pdf_attachment.id],
            )

            action = toast('Sent to Sign', 'F-0011 was sent to the employee signer.', 'success', False, reload_item(rec))
        else:
            rec.write({
                'x_sent_on': sent_on,
                'x_sign_request_state': 'lookup_failed_after_send_request',
                'x_sign_request_reference': filename,
                'x_notes': ((rec.x_notes or '') + '\nNative Odoo Sign send_request() executed for F-0011 on %s, but the generated sign.request could not be located automatically. Dynamic template ID: %s.' % (sent_on, sign_template.id)).strip(),
            })
            action = toast('Sign request lookup failed', 'Send request executed, but the generated sign.request was not found automatically. Check the Sign app.', 'warning', True, reload_item(rec))

        break

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}

sign_request_model = env['sign.request'].sudo()
attachment_model = env['ir.attachment'].sudo()
action = False


