def looks_like_certificate(attachment):
    name = (attachment.name or '').lower()
    return (
        'certificate' in name
        or 'completion' in name
        or 'completed' in name
        or 'history' in name
        or 'audit' in name
        or 'trail' in name
        or 'شهادة' in name
        or 'إكمال' in name
        or 'اكمال' in name
    )


for rec in records.sudo():
    employee = rec.x_employee_id.sudo() if rec.x_employee_id else False
    if not employee:
        action = toast('Missing employee', 'This custody item has no linked employee.', 'warning', True, reload_item(rec))
        continue

    # Sync generated PDF state first.
    if not rec.x_pdf_attachment_id:
        generated_pdf = attachment_model.search([
            ('res_model', '=', rec._name),
            ('res_id', '=', rec.id),
            ('mimetype', '=', 'application/pdf'),
            ('name', 'ilike', 'F0011'),
        ], order='create_date desc, id desc', limit=1)
        if not generated_pdf:
            generated_pdf = attachment_model.search([
                ('res_model', '=', rec._name),
                ('res_id', '=', rec.id),
                ('mimetype', '=', 'application/pdf'),
                ('name', 'ilike', 'F-0011'),
            ], order='create_date desc, id desc', limit=1)
        if generated_pdf:
            rec.write({
                'x_pdf_attachment_id': generated_pdf.id,
                'x_generated_on': rec.x_generated_on or generated_pdf.create_date or datetime.datetime.now(),
                'x_state': 'generated',
            })

    elif rec.x_state == 'draft':
        rec.write({
            'x_generated_on': rec.x_generated_on or rec.x_pdf_attachment_id.create_date or datetime.datetime.now(),
            'x_state': 'generated',
        })

    if not rec.x_sign_request_res_id:
        action = toast('PDF state synced', 'No linked Odoo Sign request was found yet. PDF generation state has been refreshed where possible.', 'success', False, reload_item(rec))
        continue

    sign_request = sign_request_model.browse(rec.x_sign_request_res_id)
    if not sign_request.exists():
        rec.write({'x_sign_request_state': 'missing_sign_request'})
        action = toast('Missing Sign request', 'The linked Odoo Sign request no longer exists or cannot be accessed.', 'warning', True, reload_item(rec))
        continue

    request_state = sign_request.state or 'unknown'

    values = {
        'x_sign_request_state': request_state,
        'x_sign_request_reference': sign_request.reference or rec.x_sign_request_reference,
    }

    if request_state not in ('signed', 'completed'):
        if rec.x_state != 'signature_requested':
            values['x_state'] = 'signature_requested'
        if not rec.x_sent_on:
            values['x_sent_on'] = sign_request.create_date or datetime.datetime.now()
        rec.write(values)
        employee.message_post(
            body='تمت مزامنة حالة توقيع F-0011. الحالة الحالية: %s.' % request_state,
            subtype_xmlid='mail.mt_note',
        )
        action = toast('Sign state synced', 'F-0011 Sign request is currently: %s.' % request_state, 'warning', False, reload_item(rec))
        continue

    completed_attachments = sign_request.completed_document_attachment_ids

    related_attachments = attachment_model.search([
        ('res_model', '=', 'sign.request'),
        ('res_id', '=', sign_request.id),
        ('mimetype', '=', 'application/pdf'),
    ], order='create_date desc, id desc')

    employee_attachments = attachment_model.search([
        ('res_model', '=', 'hr.employee'),
        ('res_id', '=', employee.id),
        ('mimetype', '=', 'application/pdf'),
    ], order='create_date desc, id desc')

    custody_attachments = attachment_model.search([
        ('res_model', '=', rec._name),
        ('res_id', '=', rec.id),
        ('mimetype', '=', 'application/pdf'),
    ], order='create_date desc, id desc')

    all_attachments = completed_attachments | related_attachments | employee_attachments | custody_attachments

    signed_native = False
    certificate_native = False

    for attachment in all_attachments:
        if rec.x_pdf_attachment_id and attachment.id == rec.x_pdf_attachment_id.id:
            continue
        if looks_like_certificate(attachment):
            if not certificate_native:
                certificate_native = attachment
        elif not signed_native:
            signed_native = attachment

    if not signed_native:
        rec.write({
            'x_sign_request_state': 'signed_no_business_document_found',
            'x_notes': ((rec.x_notes or '') + '\nOdoo Sign request %s is signed, but no signed business PDF was found during F-0011 sync on %s.' % (sign_request.id, datetime.datetime.now())).strip(),
        })
        action = toast('Signed PDF not found', 'The Sign request is signed, but the completed signed PDF was not found yet. Try Sync again after Odoo finishes processing.', 'warning', True, reload_item(rec))
        continue

    signed_copy = rec.x_signed_attachment_id
    if signed_copy and looks_like_certificate(signed_copy):
        signed_copy = False
    if signed_copy and rec.x_pdf_attachment_id and signed_copy.id == rec.x_pdf_attachment_id.id:
        signed_copy = False

    if not signed_copy:
        signed_name = signed_native.name or ('Signed F-0011 - %s.pdf' % (employee.name or rec.x_document_reference or rec.id))
        if signed_native.res_model == 'hr.employee' and signed_native.res_id == employee.id:
            signed_copy = signed_native
        else:
            signed_copy = signed_native.copy({
                'name': signed_name,
                'res_model': 'hr.employee',
                'res_id': employee.id,
            })

    certificate_copy = rec.x_sign_certificate_attachment_id
    if not certificate_copy and certificate_native:
        certificate_name = certificate_native.name or ('Sign Certificate F-0011 - %s.pdf' % (employee.name or rec.x_document_reference or rec.id))
        if certificate_native.res_model == 'hr.employee' and certificate_native.res_id == employee.id:
            certificate_copy = certificate_native
        else:
            certificate_copy = certificate_native.copy({
                'name': certificate_name,
                'res_model': 'hr.employee',
                'res_id': employee.id,
            })

    signed_on = False
    if sign_request.write_date:
        signed_on = sign_request.write_date

    signer_items = sign_request.request_item_ids.filtered(lambda item: item.state == 'completed')
    for signer_item in signer_items:
        if signer_item.write_date and (not signed_on or signer_item.write_date > signed_on):
            signed_on = signer_item.write_date

    if not signed_on and sign_request.completion_date:
        signed_on = datetime.datetime.combine(sign_request.completion_date, datetime.time(12, 0, 0))

    if not signed_on:
        signed_on = datetime.datetime.now()

    write_vals = {
        'x_state': 'signed',
        'x_signed_on': signed_on,
        'x_signed_attachment_id': signed_copy.id,
        'x_sign_request_state': request_state,
        'x_sign_request_reference': sign_request.reference or rec.x_sign_request_reference,
        'x_sign_request_url': rec.x_sign_request_url or ('/odoo/sign/%s' % sign_request.id),
        'x_notes': ((rec.x_notes or '') + '\nNative Odoo Sign completion synced for F-0011 on %s. Sign request ID: %s. Signed artifact: %s.' % (datetime.datetime.now(), sign_request.id, signed_copy.name)).strip(),
    }

    if not rec.x_sent_on:
        write_vals['x_sent_on'] = sign_request.create_date or signed_on

    if certificate_copy:
        write_vals['x_sign_certificate_attachment_id'] = certificate_copy.id

    rec.write(write_vals)

    attachment_ids = [signed_copy.id]
    if certificate_copy:
        attachment_ids.append(certificate_copy.id)

    employee.message_post(
        body='تم توقيع نموذج استلام البطاقة التعريفية F-0011 عبر توقيع أودو وربط النسخة الموقعة والشهادة، عند توفرها، بسجل الموظف.',
        subtype_xmlid='mail.mt_note',
        attachment_ids=attachment_ids,
    )

    action = toast('F-0011 signed', 'F-0011 Sign result was synced and the signed PDF was copied to the employee record.', 'success', False, reload_item(rec))
    break

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}

action = False
for rec in records.sudo():
    attachment = rec.x_signed_attachment_id
    if attachment:
        action = {
            'type': 'ir.actions.act_url',
            'url': '/web/content/%s?download=true' % attachment.id,
            'target': 'self',
        }
    else:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Download Signed PDF',
                'message': 'No signed PDF is linked to this custody item yet.',
                'type': 'warning',
                'sticky': False,
            }
        }
    break
if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}

action = False
for rec in records.sudo():
    attachment = rec.x_sign_certificate_attachment_id
    if attachment:
        action = {
            'type': 'ir.actions.act_url',
            'url': '/web/content/%s?download=true' % attachment.id,
            'target': 'self',
        }
    else:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Download Sign Certificate',
                'message': 'No Sign certificate is linked to this custody item yet.',
                'type': 'warning',
                'sticky': False,
            }
        }
    break
if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}
